// ---------------------------- helpers --------------------------------
function toObj(x) {
  if (typeof x === "string") {
    try {
      return JSON.parse(x)
    } catch (e) {
      return null
    }
  }
  return x
}
function codeOf(cc) {
  // CodeableConcept -> code (fallback: text)
  if (!cc) return ""
  if (cc.coding && cc.coding.length && cc.coding[0].code != null)
    return String(cc.coding[0].code)
  if (cc.text != null) return String(cc.text)
  return ""
}
function displayOf(cc) {
  // CodeableConcept -> display (fallback: code)
  if (!cc || !cc.coding || !cc.coding.length) return ""
  var c = cc.coding[0]
  return String(c.display != null ? c.display : c.code != null ? c.code : "")
}
function noSpace(s) {
  return String(s || "").replace(/\s+/g, "")
}
function stripDots(s) {
  return String(s || "").replace(/\./g, "")
}
function endsWith(str, suffix) {
  str = String(str || "")
  return (
    str.length >= suffix.length &&
    str.indexOf(suffix, str.length - suffix.length) !== -1
  )
}
function findExt(list, suffix) {
  // extension[] -> entry whose url ends with suffix
  var arr = list || []
  for (var i = 0; i < arr.length; i++) {
    if (endsWith(arr[i].url, suffix)) return arr[i]
  }
  return null
}
function identifierByTypeCode(identifiers, typeCode) {
  var arr = identifiers || []
  for (var i = 0; i < arr.length; i++) {
    var t = arr[i].type && arr[i].type.coding ? arr[i].type.coding : []
    for (var j = 0; j < t.length; j++) {
      if (t[j].code === typeCode)
        return arr[i].value != null ? String(arr[i].value) : ""
    }
  }
  return ""
}
function parseDate(s) {
  // "YYYY-MM-DD" -> {y,m,d} (no timezone issues)
  var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(s || ""))
  return m ? { y: +m[1], m: +m[2], d: +m[3] } : null
}
function ageOn(birth, onDate) {
  var b = parseDate(birth),
    d = parseDate(onDate)
  if (!b || !d) return null
  var age = d.y - b.y
  if (d.m < b.m || (d.m === b.m && d.d < b.d)) age--
  return age
}
function roleCode(ct) {
  return ct && ct.role ? codeOf(ct.role) : ""
}
function identifierEntryByTypeCode(identifiers, typeCode) {
  var arr = identifiers || []
  for (var i = 0; i < arr.length; i++) {
    var t = arr[i].type && arr[i].type.coding ? arr[i].type.coding : []
    for (var j = 0; j < t.length; j++) {
      if (t[j].code === typeCode) return arr[i]
    }
  }
  return null
}
function partnerFromSystem(sys) {
  // ".../identifier/partner/ibx" -> "ibx"
  var m = /\/partner\/([^\/\s]+)\s*$/.exec(String(sys || ""))
  return m ? m[1].toLowerCase() : ""
}

// ------------------------ resource lookup ----------------------------
var input = toObj(payload) || {}
if (input instanceof Array) {
  // payload array mein aaye to unwrap
  if (input.length === 1) input = toObj(input[0]) || {}
  else input = { entry: input }
}
var bundle =
  input.params && input.params.bundle
    ? input.params.bundle
    : input.bundle
    ? input.bundle
    : input
var entries = bundle.entry || []

var byRef = {}
var eobs = []
for (var e = 0; e < entries.length; e++) {
  var r = entries[e].resource
  if (!r) continue
  if (entries[e].fullUrl) byRef[entries[e].fullUrl] = r
  if (r.resourceType && r.id) byRef[r.resourceType + "/" + r.id] = r
  if (r.resourceType === "ExplanationOfBenefit") eobs.push(r)
}
function resolve(ref) {
  return ref && ref.reference && byRef[ref.reference]
    ? byRef[ref.reference]
    : null
}

// --------------------------- one EOB ---------------------------------
function flattenEob(eob) {
  var typeRaw = codeOf(eob.type).toLowerCase()
  var claimType =
    typeRaw === "institutional" ? "i" : typeRaw === "professional" ? "p" : ""

  // linked resources
  var patient = resolve(eob.patient)
  var coverage = null
  var ins = eob.insurance || []
  for (var a = 0; a < ins.length; a++) {
    if (ins[a].focal !== false) {
      coverage = resolve(ins[a].coverage)
      break
    }
  }
  var employer = coverage ? resolve(coverage.policyHolder) : null

  // Employer ID  -> EIN (as per mapping sheet)
  var employerId = ""
  if (employer && employer.identifier) {
    for (var q = 0; q < employer.identifier.length; q++) {
      var idn = employer.identifier[q]
      if (
        String(idn.system || "").indexOf("us-ein") !== -1 ||
        identifierByTypeCode([idn], "TAX")
      ) {
        employerId = String(idn.value)
        break
      }
    }
  }
  // Group ID (extension first, then Coverage.class[group])
  var groupExt = findExt(eob.extension, "group-id-extension")
  var groupId = groupExt && groupExt.valueString ? groupExt.valueString : ""
  if (!groupId && coverage && coverage["class"]) {
    for (var g = 0; g < coverage["class"].length; g++) {
      if (codeOf(coverage["class"][g].type) === "group") {
        groupId = String(coverage["class"][g].value)
        break
      }
    }
  }

  // diagnosis map (by sequence) + DRG
  var dxBySeq = {}
  var drgCode = ""
  var dxList = eob.diagnosis || []
  for (var d = 0; d < dxList.length; d++) {
    var dx = dxList[d]
    var isDrg = false
    var types = dx.type || []
    for (var t = 0; t < types.length; t++) {
      if (codeOf(types[t]).toLowerCase() === "drg") isDrg = true
    }
    var dcode = codeOf(dx.diagnosisCodeableConcept)
    dxBySeq[dx.sequence] = { code: dcode, isDrg: isDrg }
    if (isDrg && !drgCode) drgCode = dcode
  }

  // claim-level rendering provider (fallback for provider block)
  function pickRendering(item) {
    var team = eob.careTeam || []
    var seqs = item && item.careTeamSequence ? item.careTeamSequence : []
    var i, ct
    for (i = 0; i < team.length; i++) {
      // 1) rendering listed on this line
      ct = team[i]
      if (
        seqs.indexOf(ct.sequence) !== -1 &&
        roleCode(ct) === "rendering" &&
        ct.qualification
      )
        return ct
    }
    for (i = 0; i < team.length; i++) {
      // 2) any rendering on the claim
      ct = team[i]
      if (roleCode(ct) === "rendering" && ct.qualification) return ct
    }
    return null
  }
  var claimRendering = pickRendering(null)

  // TPA claim id / partner name
  var claimIdent = identifierEntryByTypeCode(eob.identifier, "claim-partner")
  var tpaClaimId =
    claimIdent && claimIdent.value != null ? String(claimIdent.value) : ""
  var partnerName = claimIdent ? partnerFromSystem(claimIdent.system) : ""
  if (!partnerName) {
    // fallback: any identifier carrying .../partner/<x>
    var eIds = eob.identifier || []
    for (var pi = 0; pi < eIds.length && !partnerName; pi++)
      partnerName = partnerFromSystem(eIds[pi].system)
  }

  // member
  var name =
    patient && patient.name && patient.name.length ? patient.name[0] : {}
  var gender =
    patient && patient.gender ? String(patient.gender).toLowerCase() : ""
  var memberId = patient
    ? identifierByTypeCode(patient.identifier, "MB") ||
      identifierByTypeCode(patient.identifier, "coupe")
    : ""

  // lines
  var items = eob.item || []
  var claimLines = []
  var total = 0
  var currency = "USD"
  var firstServiceDate = ""

  for (var n = 0; n < items.length; n++) {
    var it = items[n]

    var serviceDate =
      it.servicedDate ||
      (it.servicedPeriod && it.servicedPeriod.start
        ? it.servicedPeriod.start
        : "")
    if (!firstServiceDate && serviceDate) firstServiceDate = serviceDate

    // modifiers (can be many) -> "26|RT"
    var mods = []
    var mArr = it.modifier || []
    for (var m = 0; m < mArr.length; m++) {
      var mc = codeOf(mArr[m])
      if (mc) mods.push(mc)
    }

    // diagnosis codes for this line (no DRG, dots removed) -> "I219|4019"
    var dxCodes = []
    var dSeq = it.diagnosisSequence || []
    for (var s = 0; s < dSeq.length; s++) {
      var hit = dxBySeq[dSeq[s]]
      if (hit && !hit.isDrg && hit.code) dxCodes.push(stripDots(hit.code))
    }

    // rendering provider taxonomy for this line (no spaces)
    var rend = pickRendering(it)
    var taxonomy = rend ? noSpace(displayOf(rend.qualification)) : ""

    // line id (TPA line number) / preventive flag / amounts
    var tpa = findExt(it.extension, "tpa-claim-line-number-extension")
    var lineItemId =
      tpa && tpa.valueString != null
        ? isNaN(parseInt(tpa.valueString, 10))
          ? tpa.valueString
          : parseInt(tpa.valueString, 10)
        : it.sequence
    var prev = findExt(it.extension, "preventative-indicator-extension")
    var isPreventive = prev && prev.valueBoolean === true ? true : false // missing => false

    var submitted = null,
      allowed = null
    var adj = it.adjudication || []
    for (var j = 0; j < adj.length; j++) {
      var ac = codeOf(adj[j].category)
      if (ac === "submitted")
        submitted = adj[j].amount ? adj[j].amount.value : null
      if (ac === "eligible")
        allowed = adj[j].amount ? adj[j].amount.value : null
    }
    var charge =
      it.net && it.net.value != null
        ? it.net.value
        : submitted != null
        ? submitted
        : 0
    if (it.net && it.net.currency) currency = it.net.currency
    total += Number(charge) || 0

    claimLines.push({
      lineNumber: it.sequence,
      lineItemId: lineItemId,
      serviceDate: serviceDate,
      billType: claimType === "i" ? codeOf(eob.subType) : "",
      revenueCode: it.revenue ? codeOf(it.revenue) : "",
      placeOfService: codeOf(it.locationCodeableConcept),
      taxonomySpecialty: taxonomy,
      cptHcpcsCode: codeOf(it.productOrService),
      modifierCode: mods.join("|"),
      diagnosisCode: dxCodes.join("|"),
      drgCode: claimType === "i" ? drgCode : "",
      specialtyId: "", // NOT in payload (open question with team)
      units: it.quantity && it.quantity.value != null ? it.quantity.value : 1,
      chargeAmount: Number(charge) || 0,
      // --- extra keys needed by preventive / $0-allowed logic ---
      isPreventive: isPreventive,
      allowedAmount: allowed,
    })
  }

  var outcome = String(eob.outcome || "").toLowerCase()
  var claimStatus = outcome === "queued" ? "PENDING" : outcome.toUpperCase()

  return {
    claimId: eob.id || "",
    claimNumber:
      identifierByTypeCode(eob.identifier, "claim-partner") ||
      (eob.identifier && eob.identifier.length
        ? String(eob.identifier[0].value)
        : ""),
    tpaClaimId: tpaClaimId, // identifier type "claim-partner"
    partnerName: partnerName, // from identifier system URL .../partner/<name> (lowercase)
    claimType: claimType,
    claimStatus: claimStatus,
    employerId: employerId, // EIN (confirm format with team)
    groupId: groupId,
    member: {
      memberId: memberId,
      firstName: name.given && name.given.length ? name.given[0] : "",
      lastName: name.family || "",
      dateOfBirth: patient && patient.birthDate ? patient.birthDate : "",
      gender:
        gender === "female"
          ? "F"
          : gender === "male"
          ? "M"
          : gender
          ? gender.charAt(0).toUpperCase()
          : "",
      age: ageOn(
        patient ? patient.birthDate : "",
        firstServiceDate || (eob.billablePeriod ? eob.billablePeriod.start : "")
      ),
    },
    provider: {
      npi:
        eob.provider && eob.provider.identifier
          ? String(eob.provider.identifier.value)
          : "",
      providerName:
        eob.provider && eob.provider.display ? eob.provider.display : "",
      taxonomySpecialty: claimRendering
        ? noSpace(displayOf(claimRendering.qualification))
        : "",
      specialtyId: "", // NOT in payload
    },
    claimLines: claimLines,
    financials: {
      totalChargeAmount: total,
      currency: currency,
    },
  }
}

// ----------------------------- output --------------------------------
var result = []
for (var k = 0; k < eobs.length; k++) result.push(flattenEob(eobs[k]))
result

